"""Build the keygen tune: writes an FT2 batch file, runs it, saves + renders."""
import json, os, subprocess, sys, math
sys.path.insert(0, '/workspace')
from tune_data import *

ROWS = 64
NCH = 8
BPM, SPEED = 150, 6

# ------------------------------------------------------------------ pattern
class Pat:
    def __init__(self):
        self.cells = {}          # (ch,row) -> dict
        self.state = {}          # ch -> (end_row, vol, has_fade)
    def put(self, ch, row, midi, length, vol, inst, fx=None, param=0, cell=None):
        row = int(row)
        if row >= ROWS: return
        # close the previous note on this channel with a volume fade
        st = self.state.get(ch)
        if st and st[0] < row and not st[2]:
